from scipy.optimize import least_squares
rng=np.random.default_rng(1)
v=np.sum((dA_dt-dA_dt.mean())**2)
def fit(nterms,trials=120):
    best=(np.inf,None)
    for _ in range(trials):
        p0=[]
        for k in range(nterms):
            p0+= [rng.normal(0,3), rng.uniform(0,2), rng.uniform(0,3)]
        def res(p):
            out=np.zeros_like(dA_dt)
            for k in range(nterms):
                out+=p[3*k]*t**p[3*k+1]*A**p[3*k+2]
            return out-dA_dt
        try:
            r=least_squares(res,np.array(p0),max_nfev=500)
            if np.isfinite(r.cost) and r.cost<best[0]: best=(r.cost,r.x)
        except Exception as e:
            pass
    return best
for n in [2,3]:
    c,x=fit(n)
    print(n,"NMSE",2*c/v, np.round(x,4))
